'use strict';
// Recover transient asset failures without leaving a broken product photo.
const imageAttempts=new WeakMap();
function retryImage(image){
  if(!(image instanceof HTMLImageElement)||!image.getAttribute('src'))return;
  const failed=image.src,url=new URL(failed,location.href);
  if(url.origin!==location.origin)return;
  url.searchParams.delete('image_retry');
  const key=url.href,previous=imageAttempts.get(image),attempt=previous?.key===key?previous.attempt+1:1;
  if(attempt>2)return;
  imageAttempts.set(image,{key,attempt});
  setTimeout(()=>{
    if(!image.isConnected||image.src!==failed)return;
    url.searchParams.set('image_retry',String(attempt));
    image.src=url.href;
  },attempt*700);
}
document.addEventListener('error',event=>retryImage(event.target),true);
document.querySelectorAll('img[src]').forEach(image=>{if(image.complete&&!image.naturalWidth)retryImage(image);});
