function renderCart(){$('#bag-count').textContent=cart.reduce((sum,i)=>sum+i.qty,0);$('#bag-bottom').hidden=!cart.length;$('#bag-items').innerHTML=cart.length?cart.map(i=>`<div class="bag-item"><div class="item-thumbnail ${i.type==='sensory'?'sensory':''}" ${i.type==='name'?`style="color:${nameItemColor(i,'initialColor')?.hex||'#343b31'}"`:''}>${i.type==='name'?escape(i.initial):i.type==='catalog'?`<img src="${escape(products.find(p=>p.id===i.productId).images[0])}" alt="">`:'YUMA'}</div><div><div class="item-name">${escape(itemTitle(i))}</div><p class="item-detail">${escape(itemDetail(i))}</p><div class="item-actions"><span><button data-quantity="-1" data-id="${escape(i.id)}" aria-label="${t('Decrease quantity','Reducir cantidad')}">−</button> &nbsp; ${i.qty} &nbsp; <button data-quantity="1" data-id="${escape(i.id)}" aria-label="${t('Increase quantity','Aumentar cantidad')}">+</button></span><span>${money(i.price*i.qty)}</span><button data-remove="${escape(i.id)}">${t('Remove','Quitar')}</button></div></div></div>`).join(''):`<div class="empty-bag">${t('Your bag is empty. Start with a name or a color.','Tu bolsa está vacía. Empieza con un nombre o un color.')}<a href="${homeUrl('shop')}" id="empty-shop">${t('Explore the collection ↗','Ver la colección ↗')}</a></div>`;$$('[data-remove]').forEach(b=>b.addEventListener('click',()=>{cart=cart.filter(i=>i.id!==b.dataset.remove);storeCart();}));$$('[data-quantity]').forEach(b=>b.addEventListener('click',()=>{const i=cart.find(i=>i.id===b.dataset.id);i.qty+=Number(b.dataset.quantity);if(i.qty<1)cart=cart.filter(v=>v.id!==i.id);if(i.qty>10)i.qty=10;storeCart();}));$('#empty-shop')?.addEventListener('click',()=>$('#bag-dialog').close());$('#bag-totals').innerHTML=totalsHtml();const o=totals();$('#shipping-progress').textContent=delivery==='pickup'?t('We will arrange your pickup in Katy, TX.','Coordinaremos tu retiro en Katy, TX.'):o.subtotal>=5000?t('Your order qualifies for free shipping.','Tu pedido tiene envío gratis.'):t(`Add ${money(5000-o.subtotal)} for free shipping.`,`Añade ${money(5000-o.subtotal)} para obtener envío gratis.`);}
