function updateLetteringPreview(product,draft){
 const box=$('#lettering-preview');if(!box)return;
 const nameFields=productTextFields(product,draft).filter(field=>['name','first-name','second-name'].includes(field.key));
 box.replaceChildren();
 if(product.id==='initial-name'){
  const initial=document.createElement('span');initial.className='preview-initial';initial.textContent=draft.text.initial?.trim()||'E';initial.style.color=variantColors.find(c=>c.id===draft.baseColor)?.hex||'#83b8c9';box.append(initial);
 }
 for(const field of nameFields){const span=document.createElement('span');span.className='preview-name';span.style.fontFamily=fontFamily(draft.font);span.style.color=variantColors.find(c=>c.id===(field.key==='second-name'?draft['lower-name']:draft.detailColor))?.hex||'#a75368';span.textContent=draft.text[field.key]?.trim()||(product.id==='charms-keychain'?'Laura':'Emma');box.append(span);}
 fitLetteringPreview();
 document.fonts?.ready.then(()=>{if(box.isConnected)fitLetteringPreview();});
}
function fitLetteringPreview(){
 const box=$('#lettering-preview');if(!box||!box.clientWidth)return;
 const context=document.createElement('canvas').getContext('2d');if(!context)return;
 const available=box.clientWidth-12;
 box.querySelectorAll('.preview-name').forEach(span=>{
  span.style.fontSize='';
  const style=getComputedStyle(span),base=parseFloat(style.fontSize);
  context.font=`${style.fontStyle} ${style.fontWeight} ${base}px ${style.fontFamily}`;
  const measured=context.measureText(span.textContent).width;
  if(measured>available)span.style.fontSize=`${Math.max(12,base*available/(measured+8))}px`;
 });
}
window.addEventListener('resize',fitLetteringPreview);
