function setFieldError(control,message){
 if(!control)return;const wrapper=control.closest('label')||control.parentElement;
 wrapper.classList.toggle('field-invalid',Boolean(message));control.setAttribute('aria-invalid',String(Boolean(message)));
 let feedback=wrapper.querySelector(':scope > .inline-error');
 if(!feedback){feedback=document.createElement('span');feedback.className='inline-error';feedback.id=control.id+'-error';wrapper.append(feedback);}
 feedback.textContent=message||'';
 const description=(control.getAttribute('aria-describedby')||'').split(/\s+/).filter(id=>id&&id!==feedback.id);if(message)description.push(feedback.id);
 if(description.length)control.setAttribute('aria-describedby',description.join(' '));else control.removeAttribute('aria-describedby');
}
function refreshProductValidation(product,draft){
 const attempted=attemptedProducts.has(product.id),fields=productColorFields(product,draft);
 for(const field of fields){let message='';if(attempted&&!product.personalization.colors.includes(draft[field.key]))message=t('Choose a color.','Elige un color.');else if(attempted&&product.personalization.color_mode==='bicolor'&&draft.baseColor&&draft.baseColor===draft.detailColor)message=t('Choose two different colors.','Elige dos colores diferentes.');setFieldError($('#piece-colors [data-component="'+field.key+'"]'),message);}
 for(const field of productTextFields(product,draft))setFieldError($('#product-text-'+field.key),attempted?textFieldError(field,draft.text[field.key]):'');
 if(product.personalization.type==='social')draft.profiles.forEach((profile,index)=>{setFieldError($('#social-network-'+index),attempted&&!profile.network.trim()?t('Enter the social network.','Escribe la red social.'):'');setFieldError($('#social-handle-'+index),attempted&&!profile.handle.trim()?t('Enter the profile name or username.','Escribe el nombre del perfil o usuario.'):'');});
 const error=attempted?productDraftError(product,draft):'';$('#product-options-error').textContent=error?t('Complete the fields marked in red.','Completa los campos marcados en rojo.'):'';return error;
}
