async function loadStripeStatus(){if(isOffline)return;try{const response=await fetch('/api/checkout/status',{credentials:'same-origin',cache:'no-store'});if(response.ok){const status=await response.json();stripeState={configured:status.configured===true&&['test','live'].includes(status.mode),mode:status.mode};refreshStripeLabels();}}catch{}}
async function stripePayload(){
 const items=cart.map(item=>{if(item.type!=='catalog'||!item.customization)throw new Error(t('Remove older preview items and add them again before paying.','Quita los productos de la versión anterior y vuelve a añadirlos antes de pagar.'));const product=products.find(p=>p.id===item.productId);const snapshot=item.customization;const design=product.personalization.design_options?.find(d=>d.id===snapshot.designId);const fields=[...(product.personalization.text_fields||[]),...(design?.extra_text_fields||[])];const text=Object.fromEntries(fields.map(field=>[field.key,snapshot.textFields?.find(value=>value.label.en===field.label.en)?.value||'']));return {productId:product.id,quantity:item.qty,options:{designId:snapshot.designId,colors:snapshot.values,text,profiles:snapshot.profiles,font:snapshot.font||'Allura'}};});
 const payload={items,delivery,language:lang};const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(payload)));const fingerprint=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');let attempt;try{attempt=JSON.parse(sessionStorage.getItem('yuma-checkout-attempt')||'null');}catch{}if(!attempt||attempt.fingerprint!==fingerprint){attempt={fingerprint,nonce:crypto.randomUUID()};try{sessionStorage.setItem('yuma-checkout-attempt',JSON.stringify(attempt));}catch{}}return {...payload,nonce:attempt.nonce};
}
$('#stripe-pay').addEventListener('click',async()=>{if(stripeBusy||!stripeState.configured)return;stripeBusy=true;refreshStripeLabels();$('#stripe-pay-error').textContent='';try{const response=await fetch('/api/checkout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(await stripePayload())});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error((lang==='es'&&data.error_es)||data.error||t('Checkout could not be opened.','No se pudo abrir el pago.'));if(!/^https:\/\/checkout\.stripe\.com\//.test(data.url))throw new Error(t('Invalid checkout URL.','El enlace de pago no es válido.'));location.assign(data.url);}catch(error){$('#stripe-pay-error').textContent=error.message;stripeBusy=false;refreshStripeLabels();}});
// Back button from Stripe Checkout restores this page from cache: unlock the pay button.
addEventListener('pageshow',event=>{if(event.persisted&&stripeBusy){stripeBusy=false;refreshStripeLabels();}});
// Stripe sends cancelled checkouts back to /?checkout=cancelled#shop: keep the bag and say so.
(function checkoutCancelled(){const params=new URLSearchParams(location.search);if(params.get('checkout')!=='cancelled')return;params.delete('checkout');try{history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);}catch{}toast('Payment cancelled. Your bag is still saved.','Pago cancelado. Tu bolsa sigue guardada.');if(cart.length){renderCart();dialog('bag-dialog');}})();
loadStripeStatus();
